if('serviceWorker' in navigator&&/^https?:$/.test(location.protocol)){window.addEventListener('load',()=>{navigator.serviceWorker.register('./sw.js',{scope:'./'}).then(r=>{function ready(w){if(w?.state==='activated')announce();else w?.addEventListener('statechange',()=>{if(w.state==='activated')announce()})}function announce(){let n=document.createElement('p');n.textContent='Pronto para uso offline';n.className='offline-ready';document.querySelector('aside').append(n)}if(r.active)announce();else ready(r.installing);r.addEventListener('updatefound',()=>ready(r.installing))}).catch(()=>console.warn('A preparação para uso offline não foi concluída.'))})}